CREATE TRIGGER products_fts_ai AFTER INSERT ON products BEGIN
  INSERT INTO product_fts(rowid, name, barcode, code, brand, category) VALUES (new.rowid, new.name, new.barcode, new.code, new.brand, new.category);
END;

CREATE TRIGGER products_fts_ad AFTER DELETE ON products BEGIN
  INSERT INTO product_fts(product_fts, rowid, name, barcode, code, brand, category) VALUES ('delete', old.rowid, old.name, old.barcode, old.code, old.brand, old.category);
END;

CREATE TRIGGER products_fts_au AFTER UPDATE OF name, barcode, code, brand, category ON products BEGIN
  INSERT INTO product_fts(product_fts, rowid, name, barcode, code, brand, category) VALUES ('delete', old.rowid, old.name, old.barcode, old.code, old.brand, old.category);
  INSERT INTO product_fts(rowid, name, barcode, code, brand, category) VALUES (new.rowid, new.name, new.barcode, new.code, new.brand, new.category);
END;
